    $updated = 0;
    $inserted = 0;

    foreach ($tracks as $t) {
        $stmt = $pdo->prepare("SELECT id FROM ashram_tracks WHERE track_key = ?");
        $stmt->execute([$t['track_key']]);
        $row = $stmt->fetch();

        if ($row) {
            $upStmt = $pdo->prepare("UPDATE ashram_tracks SET 
                title_hindi = ?,
                title_english = ?,
                subtitle_hindi = ?,
                duration_text = ?,
                audio_url = ?,
                lyrics_hindi = ?,
                display_order = ?,
                youtube_search_query = ?,
                is_published = 1
                WHERE track_key = ?");
            $upStmt->execute([
                $t['title_hindi'],
                $t['title_english'],
                $t['subtitle_hindi'],
                $t['duration_text'],
                $t['audio_url'],
                $t['lyrics_hindi'],
                $t['display_order'],
                $t['youtube_search_query'],
                $t['track_key']
            ]);
            $updated++;
        } else {
            $inStmt = $pdo->prepare("INSERT INTO ashram_tracks 
                (track_key, title_hindi, title_english, subtitle_hindi, duration_text, audio_url, lyrics_hindi, display_order, youtube_search_query, is_published)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 1)");
            $inStmt->execute([
                $t['track_key'],
                $t['title_hindi'],
                $t['title_english'],
                $t['subtitle_hindi'],
                $t['duration_text'],
                $t['audio_url'],
                $t['lyrics_hindi'],
                $t['display_order'],
                $t['youtube_search_query']
            ]);
            $inserted++;
        }
    }

    echo json_encode([
        'success' => true,
        'message' => "All {$updated} updated, {$inserted} inserted complete sacred tracks."
    ]);
} catch (Exception $e) {
    http_response_code(500);
    echo json_encode([
        'success' => false,
        'error' => $e->getMessage()
    ]);
}
